import { fetch, FetchOptions } from "node-fetch";

/**
 * Single-function API for information retrieval and storage.
 */
export class QueryAPI {
  private baseUrl: string;

  /**
   * Constructor.
   * @param {string} baseUrl - Base URL for API requests.
   */
  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
  }

  /**
   * Retrieve or store information based on provided parameters.
   * @param {QueryParams} params - Query parameters.
   * @returns {Promise<any>} A promise resolving to the query result.
   */
  public async query(params: QueryParams): Promise<any> {
    // Validation
    if (params.source && !isValidSource(params.source)) {
      throw new Error("Invalid source format.");
    }

    // Build request URL
    const url = new URL(params.source || "", this.baseUrl);

    // Build request options
    const options: FetchOptions = {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        query: params.query,
        variables: params.variables,
      }),
    };

    // Apply custom options
    options.method = params.options?.method || options.method;
    options.headers = { ...options.headers, ...params.options?.headers };

    // Execute request
    const response = await fetch(url, options);
    const data = await response.json();

    // Handle errors
    if (!response.ok) {
      const error = new Error(data.error || response.statusText);
      error.name = response.status.toString();
      throw error;
    }

    return data.result;
  }
}

